<script>
(async function(){
  const parseCSV = async () => {
    const txt = await (await fetch('../benchmark/data.csv')).text();
    const lines = txt.split(/\r?\n/);
    const header = lines[0].split(',');
    const rows = [];
    for (let i=1;i<lines.length;i++) {
      if(!lines[i]) continue;
      const cells = [];
      let cur='', inq=false;
      for(let j=0;j<lines[i].length;j++){
        const ch=lines[i][j];
        if(ch==='"'){ if(inq && lines[i][j+1]==='"'){ cur+='"'; j++; } else inq=!inq; }
        else if(ch===',' && !inq){ cells.push(cur); cur=''; }
        else cur+=ch;
      }
      cells.push(cur);
      if(cells.length===header.length){ const obj={}; header.forEach((h,k)=>obj[h]=cells[k]); rows.push(obj); }
    }
    return rows;
  };

  const d = await parseCSV();
  const n = d.length;
  const num = (v)=> Number(v||0);
  const isOA = (v)=> String(v).toLowerCase()==='true';

  const byYear={}; d.forEach(r=>{byYear[r.pub_year]=(byYear[r.pub_year]||0)+1;});
  const oaRate = (d.filter(r=>isOA(r.open_access)).length/n)*100;
  const authors = d.map(r=>num(r.authors_count)).sort((a,b)=>a-b);
  const medianAuthors = authors.length%2?authors[(authors.length-1)/2]:(authors[authors.length/2-1]+authors[authors.length/2])/2;

  const country={}; d.forEach(r=>{const c=r.country||'Unknown'; country[c]=(country[c]||0)+1;});
  const topCountries = Object.entries(country).sort((a,b)=>b[1]-a[1]);
  const top10Share = topCountries.slice(0,10).reduce((s,x)=>s+x[1],0)/n*100;

  const monthly={}; const oaMonthly={};
  d.forEach(r=>{
    const y=num(r.pub_year), m=num(r.pub_month_num);
    if(m>=1&&m<=12){
      const k=`${y}-${String(m).padStart(2,'0')}`;
      monthly[k]=(monthly[k]||0)+1;
      oaMonthly[k]=oaMonthly[k]||{oa:0,t:0};
      oaMonthly[k].t++;
      if(isOA(r.open_access)) oaMonthly[k].oa++;
    }
  });
  const monthKeys=Object.keys(monthly).sort();

  const topicMonth={};
  d.forEach(r=>{
    const t=(r.major_topic||'').trim(); const y=num(r.pub_year), m=num(r.pub_month_num);
    if(!t || !(m>=1&&m<=12)) return;
    const k=`${y}-${String(m).padStart(2,'0')}`;
    topicMonth[t]=topicMonth[t]||{};
    topicMonth[t][k]=(topicMonth[t][k]||0)+1;
  });

  const emerging=[];
