    const vals=monthKeys.map(k=>series[k]||0);
    const total=vals.reduce((a,b)=>a+b,0);
    if(total<12) continue;
    const gr=[];
    for(let i=1;i<vals.length;i++) if(vals[i-1]>0) gr.push((vals[i]-vals[i-1])/vals[i-1]);
    if(gr.length>=4){
      const avg=gr.reduce((a,b)=>a+b,0)/gr.length;
      emerging.push({topic:t,growth:avg,total});
    }
  }
  emerging.sort((a,b)=>b.growth-a.growth);
  const topEmerging=emerging.slice(0,8);

  const topic={}; d.forEach(r=>{const t=(r.major_topic||'Unspecified').trim()||'Unspecified'; topic[t]=(topic[t]||0)+1;});
  const topTopic=Object.entries(topic).sort((a,b)=>b[1]-a[1]).slice(0,10);

  const journal={}; d.forEach(r=>{const j=(r.journal||'Unknown').trim()||'Unknown'; journal[j]=(journal[j]||0)+1;});
  const topJournal=Object.entries(journal).sort((a,b)=>b[1]-a[1]).slice(0,10);

  const type={};
  d.forEach(r=>{
    const raw=(r.research_type||'Unknown');
    raw.split(/[;|]/).map(x=>x.trim()).filter(Boolean).forEach(t=>{type[t]=(type[t]||0)+1;});
  });
  const topType=Object.entries(type).sort((a,b)=>b[1]-a[1]).slice(0,8);

