  document.getElementById('kpi_emerge').textContent = topEmerging.length ? (topEmerging[0].growth*100).toFixed(1)+'% MoM' : 'N/A';

  const mk=(id,type,data,opt={})=>new Chart(document.getElementById(id),{type,data,options:{responsive:true,plugins:{legend:{display:opt.legend??true}},scales:opt.scales||{}}});
  mk('monthlyVolume','line',{labels:monthKeys,datasets:[{label:'Publications',data:monthKeys.map(k=>monthly[k]),borderColor:'#2563eb',backgroundColor:'rgba(37,99,235,.2)',tension:.2}]});
  mk('yearlyVolume','bar',{labels:Object.keys(byYear).sort(),datasets:[{label:'Publications',data:Object.keys(byYear).sort().map(y=>byYear[y]),backgroundColor:['#1d4ed8','#0ea5e9','#22c55e']}]});
  mk('topCountries','bar',{labels:topCountries.slice(0,10).map(x=>x[0]),datasets:[{label:'Publications',data:topCountries.slice(0,10).map(x=>x[1]),backgroundColor:'#0ea5e9'}]});
  mk('topTopics','bar',{labels:topTopic.map(x=>x[0]),datasets:[{label:'Publications',data:topTopic.map(x=>x[1]),backgroundColor:'#7c3aed'}]});
  mk('oaTrend','line',{labels:monthKeys,datasets:[{label:'Open Access Rate (%)',data:monthKeys.map(k=>oaMonthly[k]?(oaMonthly[k].oa/oaMonthly[k].t*100):null),borderColor:'#16a34a',backgroundColor:'rgba(22,163,74,.2)',tension:.2}]});
  mk('topJournals','bar',{labels:topJournal.map(x=>x[0]),datasets:[{label:'Publications',data:topJournal.map(x=>x[1]),backgroundColor:'#f59e0b'}]},{legend:false});
  mk('researchType','bar',{labels:topType.map(x=>x[0]),datasets:[{label:'Tagged occurrences',data:topType.map(x=>x[1]),backgroundColor:'#14b8a6'}]});
  mk('authorsByCountry','bar',{labels:cMed.map(x=>x[0]),datasets:[{label:'Median Authors',data:cMed.map(x=>x[1]),backgroundColor:'#ef4444'}]});

  const t=document.getElementById('emergingTable');
  t.innerHTML='<tr><th>Emerging Major Topic</th><th>Avg MoM Growth</th><th>Total Publications</th></tr>' +
    topEmerging.map(r=>`<tr><td>${r.topic}</td><td>${(r.growth*100).toFixed(1)}%</td><td>${r.total}</td></tr>`).join('');

  const topCountry=topCountries[0]||['N/A',0];
  const yearKeys=Object.keys(byYear).sort();
  const take=[
    `Volume concentration: ${byYear[2024]||0} publications in 2024 (${((byYear[2024]||0)/n*100).toFixed(1)}%), versus ${(byYear[2025]||0)} in 2025 and ${(byYear[2026]||0)} in early 2026, consistent with expected indexing lag.`,
    `Open-access penetration is ${oaRate.toFixed(1)}% overall; month-level variation indicates policy-sensitive changes in accessibility rather than a static publishing model.`,
    `Geographic concentration remains high: top 10 countries account for ${top10Share.toFixed(1)}% of output; ${topCountry[0]} leads with ${topCountry[1]} publications.`,
    `Collaboration intensity is stable at a median of ${medianAuthors.toFixed(1)} authors per article, supporting multi-investigator team science as the dominant production model.`,
    topEmerging.length?`Fastest-rising tracked topic is ${topEmerging[0].topic} at an average ${(topEmerging[0].growth*100).toFixed(1)}% month-over-month growth (activity-filtered), indicating a candidate area for targeted funding calls.`:'No topic met the emerging-growth threshold under current activity filters.'
  ];
  document.getElementById('takeaways').innerHTML=take.map(x=>`<li>${x}</li>`).join('');
})();
